// 把多段文本各自按 wrap 折行，段间空一行拼起来；空段保留为一个空行。
export function joinFitted(paragraphs, maxWidth) {
  return paragraphs
    .map((p) => (p === "" ? [""] : wrap(p, maxWidth)))
    .map((lines) => lines.join("\n"))
    .join("\n\n");
}

export function joinFitted(paragraphs, maxWidth) {
  const lines = [];
  paragraphs.forEach((p, i) => {
    if (i > 0) lines.push("");
    lines.push(...wrap(p, maxWidth));
  });
  return lines.join("\n");
}

